files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: #e8e8f0;
  padding: 16px;
}

.card {
  background: #2a2a3d;
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 800px;
  width: 100%;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

header {
  text-align: center;
  margin-bottom: 28px;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: #ffffff;
}

.subtitle {
  margin-top: 6px;
  font-size: 1rem;
  color: #a0a0b8;
}

.palette {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  margin-bottom: 28px;
}

.swatch {
  border-radius: 12px;
  overflow: hidden;
  background: #3a3a50;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
}

.swatch-color {
  height: 100px;
  width: 100%;
}

.swatch-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  background: #202030;
  gap: 6px;
}

.hex-code {
  font-family: 'SF Mono', 'Cascadia Code', 'Fira Code', monospace;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: #e0e0f0;
  user-select: all;
}

.lock-label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 1.1rem;
  background: transparent;
  color: #8888aa;
  transition: background 0.15s, color 0.15s, transform 0.1s;
  flex-shrink: 0;
}

.lock-label:hover {
  background: #3a3a55;
  color: #c0c0e0;
}

.lock-label:active {
  transform: scale(0.92);
}

.lock-checkbox {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  pointer-events: none;
}

.lock-checkbox:focus-visible + .lock-label {
  outline: 2px solid #7c8cf8;
  outline-offset: 2px;
}

.lock-checkbox:checked + .lock-label {
  color: #f8c84c;
  background: #3a3a55;
}

.lock-icon {
  display: inline-block;
  line-height: 1;
}

.generate-btn {
  display: block;
  width: 100%;
  padding: 16px 24px;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  color: #ffffff;
  background: #5c6cf0;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  letter-spacing: 0.3px;
}

.generate-btn:hover {
  background: #4a5ae0;
  box-shadow: 0 4px 16px rgba(92, 108, 240, 0.4);
}

.generate-btn:focus-visible {
  outline: 3px solid #a0b0ff;
  outline-offset: 3px;
}

.generate-btn:active {
  transform: scale(0.98);
  background: #3a4ad0;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }

  h1 {
    font-size: 1.5rem;
  }

  .palette {
    grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
    gap: 8px;
  }

  .swatch-color {
    height: 70px;
  }

  .hex-code {
    font-size: 0.8rem;
  }

  .lock-label {
    width: 32px;
    height: 32px;
  }
}

@media (max-width: 360px) {
  .palette {
    grid-template-columns: repeat(2, 1fr);
  }

  .swatch:last-child {
    grid-column: span 2;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  const NUM_SWATCHES = 5;

  /**
   * Generate a harmonious palette of 5 HSL colors.
   * Uses a base hue with analogous/complementary offsets.
   * @returns {Array<{h: number, s: number, l: number}>}
   */
  function generateHarmoniousPalette() {
    const baseHue = Math.floor(Math.random() * 360);
    const baseSat = 60 + Math.floor(Math.random() * 25); // 60-84
    const baseLight = 45 + Math.floor(Math.random() * 15); // 45-59

    // Harmonious hue offsets: analogous + complementary accent
    const hueOffsets = [0, 30, 60, 180, 210];
    const satVariation = [0, -10, 10, -5, 5];
    const lightVariation = [0, 10, -10, 15, -15];

    return hueOffsets.map((offset, i) => ({
      h: (baseHue + offset + 360) % 360,
      s: Math.max(30, Math.min(90, baseSat + satVariation[i])),
      l: Math.max(25, Math.min(80, baseLight + lightVariation[i]))
    }));
  }

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  }

  function hslToCss(h, s, l) {
    return `hsl(${h}, ${s}%, ${l}%)`;
  }

  // State: array of { h, s, l, locked }
  let palette = [];

  function initPalette() {
    const colors = generateHarmoniousPalette();
    palette = colors.map((c) => ({ ...c, locked: false }));
  }

  function regeneratePalette() {
    const fresh = generateHarmoniousPalette();
    palette = palette.map((swatch, i) => {
      if (swatch.locked) return swatch;
      return { ...fresh[i], locked: false };
    });
  }

  function render() {
    paletteEl.innerHTML = '';

    palette.forEach((swatch, index) => {
      const hex = hslToHex(swatch.h, swatch.s, swatch.l);
      const cssColor = hslToCss(swatch.h, swatch.s, swatch.l);

      const swatchEl = document.createElement('div');
      swatchEl.className = 'swatch';

      const colorEl = document.createElement('div');
      colorEl.className = 'swatch-color';
      colorEl.style.backgroundColor = cssColor;

      const footer = document.createElement('div');
      footer.className = 'swatch-footer';

      const hexEl = document.createElement('span');
      hexEl.className = 'hex-code';
      hexEl.textContent = hex.toUpperCase();
      hexEl.setAttribute('aria-label', `Color ${hex.toUpperCase()}`);

      const checkboxId = `lock-${index}`;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.className = 'lock-checkbox';
      checkbox.id = checkboxId;
      checkbox.checked = swatch.locked;
      checkbox.setAttribute('aria-label', `Lock color ${hex.toUpperCase()}`);

      const label = document.createElement('label');
      label.className = 'lock-label';
      label.htmlFor = checkboxId;
      label.setAttribute('title', swatch.locked ? 'Unlock color' : 'Lock color');

      const icon = document.createElement('span');
      icon.className = 'lock-icon';
      icon.textContent = swatch.locked ? '\uD83D\uDD12' : '\uD83D\uDD13';
      icon.setAttribute('aria-hidden', 'true');

      label.appendChild(icon);

      checkbox.addEventListener('change', () => {
        palette[index].locked = checkbox.checked;
        label.setAttribute('title', checkbox.checked ? 'Unlock color' : 'Lock color');
        icon.textContent = checkbox.checked ? '\uD83D\uDD12' : '\uD83D\uDD13';
      });

      footer.appendChild(hexEl);
      footer.appendChild(checkbox);
      footer.appendChild(label);

      swatchEl.appendChild(colorEl);
      swatchEl.appendChild(footer);
      paletteEl.appendChild(swatchEl);
    });
  }

  function handleGenerate() {
    regeneratePalette();
    render();
  }

  generateBtn.addEventListener('click', handleGenerate);

  // Initialize
  initPalette();
  render();
})();
